# Generate a graph with 8 vertices and between 11 and 16 edges
edges = []
# Add edges systematically
for i in range(8):
    for j in range(i+1, 8):
        if len(edges) < 13:  # Target 13 edges (between 11 and 16)
            edges.append((i, j))

print(f"Number of edges: {len(edges)}")
print(f"Edges: {edges}")

# Verify all edges satisfy 0 <= u < v < 8
for u, v in edges:
    assert 0 <= u < v < 8, f"Invalid edge: ({u}, {v})"

print("All edges are valid!")
